using HRM.Models;using HRM.Models.Recruitment;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;namespace HRM.Api.Data.EntityConfigurations;public sealed class RecruitmentResultsMapping:IEntityTypeConfiguration<RecruitmentResultPublication>,IEntityTypeConfiguration<RecruitmentMeritResult>,IEntityTypeConfiguration<RecruitmentObjection>{public void Configure(EntityTypeBuilder<RecruitmentResultPublication>b){b.ToTable("RM_RecruitmentResultPublications");b.HasKey(x=>x.Id);b.Property(x=>x.Version).IsConcurrencyToken();b.HasIndex(x=>x.RecruitmentVacancyId).IsUnique();b.HasOne<RecruitmentVacancy>().WithMany().HasForeignKey(x=>x.RecruitmentVacancyId).OnDelete(DeleteBehavior.Restrict);b.HasOne<Organisation>().WithMany().HasForeignKey(x=>x.OrganisationId).OnDelete(DeleteBehavior.Restrict);b.HasOne<OperationLog>().WithMany().HasForeignKey(x=>x.OperationLogId).OnDelete(DeleteBehavior.Restrict);}public void Configure(EntityTypeBuilder<RecruitmentMeritResult>b){b.ToTable("RM_RecruitmentMeritResults");b.HasKey(x=>x.Id);b.Property(x=>x.Score).HasPrecision(8,2);b.Property(x=>x.CalculationSnapshotJson).HasMaxLength(16000).IsRequired();b.Property(x=>x.Version).IsConcurrencyToken();b.HasIndex(x=>new{x.RecruitmentResultPublicationId,x.RecruitmentApplicationId}).IsUnique();b.HasOne<RecruitmentResultPublication>().WithMany().HasForeignKey(x=>x.RecruitmentResultPublicationId).OnDelete(DeleteBehavior.Restrict);b.HasOne<RecruitmentApplication>().WithMany().HasForeignKey(x=>x.RecruitmentApplicationId).OnDelete(DeleteBehavior.Restrict);}public void Configure(EntityTypeBuilder<RecruitmentObjection>b){b.ToTable("RM_RecruitmentObjections");b.HasKey(x=>x.Id);b.Property(x=>x.Grounds).HasMaxLength(4000).IsRequired();b.Property(x=>x.Status).HasMaxLength(30).IsRequired();b.Property(x=>x.Version).IsConcurrencyToken();b.HasIndex(x=>new{x.RecruitmentResultPublicationId,x.RecruitmentApplicationId}).IsUnique();b.HasOne<RecruitmentResultPublication>().WithMany().HasForeignKey(x=>x.RecruitmentResultPublicationId).OnDelete(DeleteBehavior.Restrict);b.HasOne<RecruitmentApplication>().WithMany().HasForeignKey(x=>x.RecruitmentApplicationId).OnDelete(DeleteBehavior.Restrict);b.HasOne<OperationLog>().WithMany().HasForeignKey(x=>x.OperationLogId).OnDelete(DeleteBehavior.Restrict);}}
